'use strict';
(()=>{const A=RepoAccount,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const manage=new URL(location.href).searchParams.get('manage')==='1';let items=[],cursor=null,busy=false;
const api=(action,body)=>A.request('/api/promotions?action='+action,{signal:AbortSignal.timeout(55000),...(body?{method:'POST',body:JSON.stringify(body)}:{})});
function render(){const labels={pending:'Awaiting approval',approved:'Approved — ready for test checkout',rejected:'Not approved',checkout:'Checkout reserved',paid_waiting:'Paid — waiting for activation',active:'Active test promotion',paused:'Paused — remaining time saved',expired:'Completed',refunded:'Refunded'};$('#promotion-list').innerHTML=items.length?items.map(p=>{const left=Math.max(0,Number(p.remaining_seconds)-(p.status==='active'&&p.active_since?(Date.now()-Date.parse(p.active_since))/1000:0)),days=left/86400;return `<article class="promotion-record"><span class="promotion-status">${esc(labels[p.status]||p.status)}</span><h3>${esc(p.snapshot.name||p.repo_name)}</h3><p><a href="https://github.com/${esc(p.repo_name)}" target="_blank" rel="noopener">${esc(p.repo_name)} ↗</a></p><p>${esc(p.snapshot.description)}</p><p>£15 · ${p.paid_at?days.toFixed(1)+' active days remaining':'30 active days after payment'} · No renewal</p>${p.review_note?`<p>Administrator: ${esc(p.review_note)}</p>`:''}${p.pause_reason?`<p>${esc(p.pause_reason)}. Your unused time is preserved.</p>`:''}${p.health_checked_at?`<p class="small">Availability checked ${esc(new Date(p.health_checked_at).toLocaleString())}</p>`:''}${manage&&['pending','approved'].includes(p.status)?`<label>Review note<textarea data-note="${p.id}" maxlength="500" placeholder="Explain your decision"></textarea></label><div class="account-actions"><button class="button lime" data-action="approved" data-id="${p.id}">Approve request</button><button class="button outline" data-action="rejected" data-id="${p.id}">Reject request</button></div>`:''}${!manage&&['approved','checkout'].includes(p.status)?`<button class="button lime" data-action="checkout" data-id="${p.id}">${p.status==='checkout'?'Continue test checkout':'Test checkout — £15'}</button><p class="small">Use Stripe test card 4242 4242 4242 4242, any future expiry and any CVC. Do not enter real card details. Leaving checkout unpaid reserves a place until Stripe expires the session (normally 24 hours).</p>`:''}${!manage&&['checkout','paid_waiting','active','paused'].includes(p.status)?`<button class="button outline" data-action="refresh" data-id="${p.id}">Check payment / availability</button>`:''}${manage&&p.payment_intent&&p.status!=='refunded'?`<button class="button outline" data-action="refund" data-id="${p.id}">Refund full test payment</button>`:''}</article>`}).join(''):'<p class="loading-note">'+(manage?'No promotion requests yet.':'No promotions yet. Submit your repository above to request approval.')+'</p>';$('#promotion-more').hidden=!cursor;$('#promotion-list').querySelectorAll('button').forEach(b=>b.disabled=busy)}
async function load(append=false){const data=await api((manage?'manage':'mine')+(append&&cursor?'&cursor='+encodeURIComponent(cursor):''));items=append?[...items,...data.items]:data.items;cursor=data.nextCursor;$('#manage-promotions-link').hidden=!data.admin;$('#sync-promotions').hidden=!manage;$('#promotion-request').hidden=manage;$('#promotion-setup').hidden=data.checkoutReady;if(!data.checkoutReady)$('#promotion-setup').textContent='Test checkout needs administrator setup: apply migration 6, configure Stripe test credentials and the signed webhook. Requests can still be reviewed; real payments are disabled.';render()}
async function task(fn){if(busy)return;busy=true;render();$('#promotion-message').textContent='';try{await fn()}catch(e){$('#promotion-message').textContent=e.message}finally{busy=false;render()}}
$('#promotion-request').onsubmit=e=>{e.preventDefault();void task(async()=>{let repo=$('#promotion-repo').value.trim();try{const url=new URL(repo);if(url.origin==='https://github.com')repo=url.pathname.replace(/^\/|\/$/g,'')}catch{}await api('request',{repo});await load();$('#promotion-message').textContent='Request submitted. An administrator will review it before you can pay.';$('#promotion-repo').value=''})};
$('#promotion-list').onclick=e=>{const button=e.target.closest('[data-action]');if(!button)return;void task(async()=>{const id=button.dataset.id,action=button.dataset.action;if(['approved','rejected'].includes(action)){const note=$(`[data-note="${id}"]`).value;await api('review',{id,decision:action,note});await load();$('#promotion-message').textContent=action==='approved'?'Approved. The owner can use test checkout.':'Request rejected.'}else if(action==='checkout'){const result=await api(action,{id});if(result.url){location.href=result.url;return}await load();$('#promotion-message').textContent='Payment status refreshed.'}else{if(action==='refund'&&!confirm('Refund the full test payment and end this promotion?'))return;await api(action,{id});await load();$('#promotion-message').textContent=action==='refund'?'Test payment refunded.':'Status checked.'}})};
$('#refresh-promotions').onclick=()=>void task(()=>load());$('#promotion-more').onclick=()=>void task(()=>load(true));$('#sync-promotions').onclick=()=>void task(async()=>{const result=await api('admin-sync',{});await load();$('#promotion-message').textContent=`Checked ${result.checked} promotions${result.failed?' · '+result.failed+' checks need retry':''}.`});
(async()=>{while(!A.ready)await new Promise(r=>setTimeout(r,50));if(!A.user){$('#promotion-gate').innerHTML='<p>Sign in with GitHub to promote your own repositories.</p><a class="button lime" href="/api/auth?action=start">Sign in with GitHub ↗</a>';return}if(manage&&!A.user.admin){$('#promotion-gate').textContent='Administrator access is required to review promotions.';return}$('#promotion-gate').hidden=true;$('#promotion-workspace').hidden=false;const repo=new URL(location.href).searchParams.get('repo');if(repo)$('#promotion-repo').value=repo;try{await load();const done=new URL(location.href).searchParams.get('checkout');if(done==='complete'){$('#promotion-message').textContent='Returned from Stripe. Activation depends on verified payment, not this redirect.';for(const p of items.filter(p=>p.status==='checkout'))await api('refresh',{id:p.id});await load()}else if(done==='cancelled')$('#promotion-message').textContent='Checkout was cancelled. No promotion starts until payment is confirmed.'}catch(e){$('#promotion-message').textContent=e.message}})();
})();
